INSERT INTO actividades (id, tema, franja, emoji, titulo, desc, color) VALUES (1, 'playa', 'manana', '☀️', 'Playa Norte', 'La más familiar y tranquila. Arena fina, aguas calmas y sombra natural.', '#1E88E5');
INSERT INTO actividades (id, tema, franja, emoji, titulo, desc, color) VALUES (2, 'playa', 'manana', '🏖️', 'Playa Honda', 'Más íntima y serena. Aguas profundas y entorno verde. Ideal para descansar.', '#1E88E5');
INSERT INTO actividades (id, tema, franja, emoji, titulo, desc, color) VALUES (3, 'playa', 'manana', '🏄', 'Playa Inkier', 'La más animada. Música, gente y energía con el Uruguay de fondo.', '#1565C0');
INSERT INTO actividades (id, tema, franja, emoji, titulo, desc, color) VALUES (4, 'playa', 'tarde', '🏝️', 'Excursión a las Islas', 'Lancha hasta islas vírgenes del delta entrerriano. Una experiencia única.', '#1E88E5');
