INSERT INTO actividades (id, tema, franja, emoji, titulo, desc, color) VALUES (7, 'historia', 'manana', '🏺', 'Museo Histórico Regional', 'La historia de Colón desde 1863. Arqueología, inmigrantes europeos y mucho más.', '#795548');
