INSERT INTO actividades (id, tema, franja, emoji, titulo, desc, color) VALUES (11, 'gastronomia', 'manana', '☕', 'Gaman Café', 'Café de especialidad y laminados artesanales. El mejor desayuno de Colón.', '#795548');
INSERT INTO actividades (id, tema, franja, emoji, titulo, desc, color) VALUES (12, 'gastronomia', 'mediodia', '🎶', 'Campo Adentro', 'Pescados de río, show folklórico y el ambiente más auténtico del litoral.', '#2E7D32');
