INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (1, 'solo', '20 Verdades de Colón', 'Tenés que adivinar un lugar o personaje de Colón. Solo podés hacer 20 preguntas con respuesta SÍ o NO.', '🧠', '5-10 min', '["Pensá en un lugar secreto de Colón","Hacete estas preguntas mentalmente","¿Está en la costanera? ¿Tiene agua? ¿Es histórico?","Descubrí de qué lugar se trata en 20 preguntas o menos"]', '{"lugares":["Molino Forclaz","Termas Colón","Playa Honda","Puerto Fluvial","Parque El Palmar","Museo Histórico"]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (2, 'solo', 'Fotógrafo Secreto', 'Misiones fotográficas para completar. Cada foto tiene un puntaje según la dificultad.', '📸', '10 min', '["Tomate 10 minutos","Completá la mayor cantidad de fotos posibles","Cada foto vale puntos","Sumalas al final"]', '{"misiones":[{"puntos":1,"tarea":"Una foto de algo azul natural"},{"puntos":2,"tarea":"El reflejo del río en algo"},{"puntos":3,"tarea":"Una foto artística del cielo"},{"puntos":2,"tarea":"Algo que solo existe en Colón"},{"puntos":3,"tarea":"Una sombra interesante"}]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (3, 'solo', 'Trivia Colonense', '¿Cuánto sabés de Colón? 10 preguntas de historia, naturaleza y cultura local.', '🏆', '5 min', '["Leé cada pregunta","Pensá tu respuesta","Verificá el resultado","Sumá 1 punto por cada acierto"]', '{"preguntas":[{"p":"¿A cuántos km está el Parque Nacional El Palmar?","r":"55 km (por Ruta 14)"},{"p":"¿Cómo se llama el molino histórico del S.XIX?","r":"Molino Forclaz"},{"p":"¿En qué año fue fundada la ciudad de Colón?","r":"1863"},{"p":"¿Qué río bordea la costa de Colón?","r":"El río Uruguay"},{"p":"¿Cuál es el pez más buscado en la pesca deportiva local?","r":"El dorado"}]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (4, 'solo', 'Bingo del Viajero', 'Cartón de bingo con cosas para ver y vivir en Colón. ¡Marcá lo que encontrés a tu alrededor!', '🎰', 'indefinido', '["Mirá el cartón","Marcá todo lo que veas o hayas hecho hoy","¿Completás una línea?"]', '{"casillas":["Palmera","Barco en el río","Heladería","Persona con mate","Bandera argentina","Cartel de playa","Bicicleta","Pájaro colorido","Puesto de artesanías","Persona haciendo running"]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (5, 'pareja', '¿Me conocés?', 'Uno escribe la respuesta a una pregunta sobre sí mismo. El otro adivina.', '💑', '15 min', '["Cada uno anota su respuesta en silencio","El otro adivina en voz alta","Comparen resultados","Gana quien más acierta"]', '{"preguntas":["¿Cuál sería tu plan ideal para este fin de semana?","¿Qué plato pedirías si fueras a Campo Adentro?","¿Preferís la playa de mañana o al atardecer?","¿Qué lugar de Colón te gustaría volver a visitar?","¿Termas o río? ¿Por qué?","¿Qué recordarías más de este viaje?"]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (6, 'pareja', 'Adivina Mi Foto', 'Uno saca una foto sin mostrarla. El otro tiene que adivinar qué fotografió solo con 5 pistas.', '📷', '10 min', '["Uno saca una foto de algo a su alrededor sin mostrarla","Da 5 pistas de a una, de más difícil a más fácil","El otro adivina cuándo puede","Más rápido = más puntos"]', '{}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (7, 'pareja', 'Este o Aquél — Colón Edition', 'Dilemas relacionados con el viaje. Turnos alternados, sin pensarlo más de 5 segundos.', '🔀', '10 min', '["Turnos alternados","Sin pensarlo más de 5 segundos","Si tarda más de 5 seg, el otro elige"]', '{"dilemas":["¿Termas o río natural?","¿Amanecer o atardecer en la costa?","¿Parrilla o pescado del río?","¿Playa sola o llena de gente?","¿Quedarse más días o explorar otro destino?","¿Kayak o excursión náutica?"]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (8, 'amigos', 'Yo nunca... en Colón', 'Versión viajera del clásico. Quien SÍ lo hizo, toma o hace una penitencia.', '🙅', '20 min', '["En ronda, cada uno dice: ''Yo nunca...'' + algo del viaje","Quien sí lo hizo, cumple la penitencia","Penitencias: contar un secreto, hacer un reto, etc."]', '{"ejemplos":["Yo nunca me tiré al río Uruguay","Yo nunca fui a las termas","Yo nunca probé el dorado a la parrilla","Yo nunca madrugué para ver el amanecer en la playa","Yo nunca me perdí en Colón"]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (9, 'amigos', 'Carrera de Conocimiento', 'Trivia en equipos sobre Colón y Entre Ríos. Primer equipo en llegar a 10 puntos gana.', '🏁', '20 min', '["Dividirse en 2 equipos","Turnos alternados de preguntas","1 punto por respuesta correcta","Primero en llegar a 10 gana"]', '{"preguntas":[{"p":"¿Qué palma es emblema del Parque El Palmar?","r":"Palma yatay"},{"p":"¿En qué provincia argentina está Colón?","r":"Entre Ríos"},{"p":"¿Cómo se llama el palacio del Gral. Urquiza cerca de Colón?","r":"Palacio San José"},{"p":"¿Qué animal autóctono abunda en el Parque El Palmar?","r":"Carpincho / yacaré"},{"p":"¿Qué puente une Colón (AR) con Paysandú (UY)?","r":"Puente Gral. Artigas"}]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (10, 'amigos', 'Reto Físico Costanero', 'Minijuegos para hacer en la costanera. Cada reto vale puntos.', '🏃', '15 min', '["Solo se necesita el cuerpo y el entorno","Un árbitro con el teléfono","Completar el reto para sumar puntos"]', '{"retos":[{"pts":1,"reto":"¿Quién llega primero a ese árbol? (sprint 20m)"},{"pts":2,"reto":"¿Quién aguanta más tiempo en equilibrio sobre un pie?"},{"pts":3,"reto":"Contar los barcos/kayaks visibles desde la orilla"},{"pts":2,"reto":"Tirar una piedra al río — ¿quién hace más rebotes?"}]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (11, 'familia', 'Buscador de Colón', 'Lista de objetos y cosas para encontrar caminando por la costanera.', '🔍', '15 min', '["Cada uno tiene la misma lista","Salen juntos a buscar","Primero en encontrar todo o más cosas en 15 min gana"]', '{"buscar":["Una piedra redonda","Algo del color naranja","Un pájaro","El nombre de una calle","Algo de madera vieja","Un barco o lancha","Una flor silvestre","La sombra de una persona"]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (12, 'familia', '¿Quién soy? — Versión Colón', 'Post-it en la frente (o usar la mano tapando). Adivinás quién sos haciendo preguntas SÍ/NO.', '🎭', '20 min', '["Un jugador piensa en un ''personaje'' o lugar de Colón","Los demás hacen preguntas de SÍ/NO","Máximo 20 preguntas"]', '{"personajes":["El Dorado","El Molino Forclaz","Las Termas","El río Uruguay","El Carpincho","La Palmera Yatay","Un kayak","La Playa Norte"]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (13, 'familia', 'Cuentacuentos del Río', 'Todos juntos inventan una historia de aventuras ambientada en Colón.', '📖', '15 min', '["Alguien empieza: ''Había una vez en Colón...''","Cada uno agrega UNA frase en su turno","La historia debe incluir: el río, un animal, una aventura"]', '{"inicio":["Había una vez un carpincho que vivía en la orilla del Uruguay...","Una tarde en la Playa Norte, una familia encontró una botella con un mapa...","El guardaparques del Palmar descubrió algo increíble entre las palmeras..."]}');
INSERT INTO juegos (id, categoria, nombre, desc, emoji, duracion, instrucciones, datos) VALUES (14, 'familia', 'Mini Olimpiadas Familiares', '5 pruebas rápidas para hacer en cualquier lugar.', '🥇', '20 min', '["5 pruebas, 5 campeones posibles","Árbitro: el que tiene el teléfono","Al final, el que ganó más pruebas es el Campeón Familiar"]', '{"pruebas":["Equilibrio: ¿quién para más tiempo en un pie con los ojos cerrados?","Memoria: mirar 10 segundos la pantalla, dar vuelta y decir de qué color era cada emoji","Velocidad mental: primero en decir 5 cosas que se ven desde acá","Artístico: mejor dibujo de un carpincho en el teléfono (notas)","Conocimiento: ¿quién sabe más capitales de provincias argentinas?"]}');
